const LIMITE_HISTORICO = 10;
const JANELA_INTERACAO_HORAS = 12;

// =====================================================
// PAYLOAD TRATADO
// =====================================================

const payload = $("payload_webhook").first().json;

// Texto atual normalizado
const texto_mensagem =
  $('Trata_mensagem').first().json.text || "";

// Data/hora atual vinda do payload
const data_atual_texto = payload.data || "";
const hora_atual_texto = payload.time || "";
const data_hora_atual_texto = `${data_atual_texto} ${hora_atual_texto}`.trim();


// =====================================================
// FUNÇÃO SIMPLES PARA DATA BR
// Formato esperado: dd/mm/yyyy HH:mm:ss
// =====================================================

function converterDataHoraBR(valor) {
  if (!valor || typeof valor !== "string") return null;

  const [data, hora = "00:00:00"] = valor.trim().split(" ");

  const [dia, mes, ano] = data.split("/").map(Number);
  const [HH = 0, MM = 0, SS = 0] = hora.split(":").map(Number);

  if (!dia || !mes || !ano) return null;

  const dataConvertida = new Date(ano, mes - 1, dia, HH, MM, SS);

  return Number.isNaN(dataConvertida.getTime()) ? null : dataConvertida;
}


// =====================================================
// HISTÓRICO
// =====================================================

let itens_historico = [];

try {
  itens_historico = $("Memory_Events").all();
} catch {
  itens_historico = [];
}

const eventos_memoria = itens_historico
  .map(item => ({
    data_hora: item.json.ts,
    mensagem_usuario: item.json.message_in,
    resposta_vita: item.json.agent_reply
  }))
  .slice(-LIMITE_HISTORICO);


// =====================================================
// MEMÓRIA EM TEXTO LEGÍVEL PARA O AGENT
// =====================================================

const contexto_memoria = eventos_memoria
  .map(evento => {
    const linhas = [];

    if (evento.data_hora) {
      linhas.push(`Data: ${evento.data_hora}`);
    }

    if (evento.mensagem_usuario) {
      linhas.push(`Usuário: ${evento.mensagem_usuario}`);
    }

    if (evento.resposta_vita) {
      linhas.push(`Vita: ${evento.resposta_vita}`);
    }

    return linhas.join("\n");
  })
  .filter(Boolean)
  .join("\n\n");


// =====================================================
// ESTADO DA CONVERSA
// =====================================================

const ultimo_evento = eventos_memoria.length
  ? eventos_memoria[eventos_memoria.length - 1]
  : null;

const ultima_data_historico = ultimo_evento?.data_hora || null;

const data_hora_atual = converterDataHoraBR(data_hora_atual_texto);
const data_hora_ultima_interacao = converterDataHoraBR(ultima_data_historico);

const possui_historico = Boolean(ultima_data_historico);

const horas_desde_ultima_interacao =
  data_hora_atual && data_hora_ultima_interacao
    ? Number(
        (
          (data_hora_atual - data_hora_ultima_interacao) /
          (1000 * 60 * 60)
        ).toFixed(2)
      )
    : null;

const estado_interacao =
  possui_historico &&
  horas_desde_ultima_interacao !== null &&
  horas_desde_ultima_interacao < JANELA_INTERACAO_HORAS
    ? "interacao_em_curso"
    : "nova_interacao";

const deve_cumprimentar = estado_interacao === "nova_interacao";


// =====================================================
// OUTPUT
// =====================================================

return [
  {
    json: {
      mensagem_atual: {
        texto: texto_mensagem,
        tipo: payload.message_type || null,
        id: payload.message_id || null,
        enviada_por_mim: payload.from_me ?? null,
        nome: payload.name || null,
        data: payload.data || null,
        hora: payload.time || null,
        timestamp: payload.message_timestamp || null
      },

      memoria: {
        contexto: contexto_memoria,
        ultima_data_historico,
        limite_historico: LIMITE_HISTORICO
      },

      estado_conversa: {
        possui_historico,
        horas_desde_ultima_interacao,
        estado_interacao,
        deve_cumprimentar
      }
    }
  }
];

const rows = ($items("consulta_buffer") ?? [])
  .map(i => i.json)
  .filter(r => r && Object.keys(r).length > 0)
  .filter(r => r.row_number !== undefined && r.row_number !== null && r.row_number !== "" && !isNaN(Number(r.row_number)))
  .map(r => ({ ...r, row_number: Number(r.row_number) }));

rows.sort((a, b) => b.row_number - a.row_number);

// se não tiver nada, retorna 0 items (não um item vazio)
return rows.map(r => ({ json: r }));

// Junta respostas do agente (buffer de resposta)
const joined = $("cria_resposta").first().json.output
  .map(i => i.texto)
  .filter(Boolean)
  .join('\n\n');

// Pega mensagem atual do webhook
const textIn = $('Trata_mensagem').first().json.text || '';

// Pega histórico do buffer corretamente
const buffer = $('consulta_buffer').all()
  .map(i => i.json.message_in)
  .filter(Boolean);

return [
  {
    json: {
      buffer: buffer,
      message_in: textIn,
      agent_response: joined
    }
  }
];

const item = $input.first().json;
const output = item.output;

// normaliza asteriscos duplicados
function limparTexto(texto) {
  return String(texto || "")
    .replace(/\*+\*/g, "*")
    .trim();
}

// quebra texto grande em blocos por linha em branco
function quebrarTexto(texto) {
  return limparTexto(texto)
    .split("\n\n")
    .map(t => t.trim())
    .filter(t => t !== "");
}

// CASO 1: já veio como array de mensagens
if (Array.isArray(output)) {
  return output
    .map((msg, index) => {
      const texto = limparTexto(msg?.texto || msg);
      if (!texto) return null;

      return {
        json: {
          numero: msg?.numero || index + 1,
          texto
        }
      };
    })
    .filter(Boolean);
}

// CASO 2: veio como string direta
if (typeof output === "string") {
  return quebrarTexto(output).map((parte, index) => ({
    json: {
      numero: index + 1,
      texto: parte
    }
  }));
}

// CASO 3: veio como objeto com campo texto
if (output && typeof output === "object" && typeof output.texto === "string") {
  return quebrarTexto(output.texto).map((parte, index) => ({
    json: {
      numero: index + 1,
      texto: parte
    }
  }));
}

// CASO 4: fallback
return [
  {
    json: {
      numero: 1,
      texto: ""
    }
  }
];

