const payload = $('payload_webhook').first().json;

const leituraImagem = $input.all()
  .map(item => item.json?.[0]?.content?.[0]?.text || '')
  .filter(Boolean)
  .join('\n\n');

const textoApoio =
  payload.text ||
  payload.caption_image_text ||
  payload.caption_pdf_text ||
  '';

const text =
  leituraImagem
    ? [textoApoio, leituraImagem].filter(Boolean).join('\n\n')
    : (
        payload.text ||
        $json.text ||
        payload.caption_pdf_text ||
        payload.caption_image_text ||
        ''
      );

return {
  json: {
    text
  },
  binary: $binary
};

const binaries = $input.first().binary || {};

return Object.entries(binaries).map(([key, file], index) => {
  return {
    json: {
      page_number: index + 1,
      file_name: file.fileName || key,
      mime_type: file.mimeType,
    },
    binary: {
      data: file,
    },
  };
});

